87	    static Object find(String s, Applicable defn) {
88	        int dot = s.lastIndexOf('.');
89	        String cls = s.substring(0, dot), name = s.substring(dot + 1);
90	        Class<?> c;
91	        try { c = Class.forName(cls); }
92	        catch (ClassNotFoundException e) { return "Native helper class " + cls + " not found."; }
93	        List<Method> named = new ArrayList<Method>();
94	        for (Method x : c.getMethods())
95	            if (x.getName().equals(name) && Modifier.isStatic(x.getModifiers())) named.add(x);
96	        if (named.isEmpty()) return "Native helper " + s + " names no static method of " + cls + ".";
97	        List<Class<?>> want = new ArrayList<Class<?>>();
98	        boolean hasSelf = false;
99	        for (Param p : NodeUtil.getParams(defn)) {
100	            String pn = p.getName().getText();
101	            if (pn.equals("self")) { hasSelf = true; continue; }
102	            Class<?> j = javaFor(p.getIdType().isSome() ? typeName(p.getIdType().unwrap()) : null);
103	            if (j == null || j == void.class)
104	                return "Native helper " + s + ": no Java type carries the declared type of parameter " + pn + ".";
105	            want.add(j);
106	        }
107	        Class<?> res = null;    // a declaration without a result type is refused by NativeApp.init
108	        if (hasResultType(defn)) {
109	            res = javaFor(declaredResult(defn));
110	            if (res == null) return "Native helper " + s + ": no Java type carries the declared result type.";
111	        }
112	        List<Method> fits = new ArrayList<Method>();
113	        for (Method x : named) {
114	            Class<?>[] xs = x.getParameterTypes();
115	            int off = xs.length - want.size();          // 1: self first
116	            if (off < 0 || off > 1 || (hasSelf && off != 1)) continue;
117	            boolean ok = (res == null || x.getReturnType() == res)
118	                         && (x.getReturnType() == void.class || carried(x.getReturnType()));
119	            for (int i = 0; ok && i < xs.length; i++) {
120	                if (!carried(xs[i])) ok = false;
121	                else if (i >= off && xs[i] != want.get(i - off)) ok = false;
122	            }
123	            if (ok) fits.add(x);
124	        }
125	        if (fits.size() == 1) return fits.get(0);
126	        if (fits.isEmpty()) return "Native helper " + s + " has no overload that fits the declaration's types.";
127	        return "Native helper " + s + " has " + fits.size() + " overloads that fit the declaration's types.";
128	    }
